    listArtifacts: {
        parameters: {
            query?: {
                /** @description Return the explicitly selected current version when accessible, otherwise the latest available and accessible version per root. Excludes trashed files. Apply before name/MIME filters and pagination. This is the default, and what the Library shows. Only an explicit `true` adds the lineage fields (`root_id`, `previous_id`, `version`) to each item. `false` returns every available version of every file, including superseded versions and files in the trash. */
                latest_only?: boolean;
                /** @description Mime prefix filter (e.g. `image/`) */
                mime?: string;
                /** @description Case-insensitive substring match on the artifact name. Filenames are how people and agents refer to a file, so this is the search key for "find the file called ...". */
                q?: string;
                /** @description Folder to list, as a relative path with no leading or trailing slash. A file's folder is the directory part of its `name`, so `reports/2026` returns `reports/2026/weekly.md`. Omit it or send an empty value for the root. */
                folder?: string;
                /** @description Include files in subfolders of `folder`. With `false`, only files whose folder is exactly `folder` are returned; at the root that means files whose name carries no folder at all. */
                recursive?: boolean;
                /** @description Only files this assistant made, in any folder. An assistant picks a folder for each file, so its files are not in one place. */
                agent_id?: string;
                /** @description Only files created by this principal (for example, an assistant's `principal_id`). With `latest_only=true`, this matches the creator of the returned current version. */
                created_by?: string;
                /** @description Narrows the listing to one section of the Library. `company` is the company's files, which everyone in the organization can read. `personal` is the caller's own files, which only the caller can read. `group` is a space, named by `group_id`, which only its members can read. Omit it to list every section the caller can read. */
                place?: components["parameters"]["LibraryPlaceParam"];
                /** @description The space's group ID, when `place` is `group`. */
                group_id?: components["parameters"]["LibraryGroupParam"];
                /** @description Cursor for pagination (opaque string from previous response) */
                cursor?: components["parameters"]["CursorParam"];
                /** @description Maximum number of items to return */
                limit?: components["parameters"]["LimitParam"];
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description OK */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ArtifactListResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            403: components["responses"]["Forbidden"];
        };
    };
